import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第三册：培养技能 · Lesson 7 Mutilated ladies","description":"学习 可数与不可数名词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 7 Mutilated ladies","description":"学习 可数与不可数名词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 可数与不可数名词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 6 Smash-and-grab","link":"/life/english/new-concept/book-3/unit-01/lesson-006"},"next":{"text":"第三册：培养技能 · Lesson 8 A famous monastery","link":"/life/english/new-concept/book-3/unit-01/lesson-008"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 6 Smash-and-grab","link":"/life/english/new-concept/book-3/unit-01/lesson-006"},"next":{"text":"第三册：培养技能 · Lesson 8 A famous monastery","link":"/life/english/new-concept/book-3/unit-01/lesson-008"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-007.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-007.md"}'),i={name:"life/english/new-concept/book-3/unit-01/lesson-007.md"};function l(s,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-7-mutilated-ladies" tabindex="-1">第三册：培养技能 · Lesson 7 Mutilated ladies <a class="header-anchor" href="#第三册-培养技能-·-lesson-7-mutilated-ladies" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 7 Mutilated ladies&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以受损纸币的识别和处理为切入点，练习写清办理流程与数量限制。这里的词汇延伸到一般物品检查，不提供现实金融业务承诺。学习区分可以数的钞票、碎片与通常不可数的金钱、损坏，避免数量表达和主谓一致互相冲突。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>banknote</td><td>/ˈbæŋknəʊt/</td><td>n.</td><td>纸币</td><td>a torn banknote</td></tr><tr><td>fragment</td><td>/ˈfræɡmənt/</td><td>n.</td><td>碎片</td><td>paper fragments</td></tr><tr><td>identify</td><td>/aɪˈdentɪfaɪ/</td><td>v.</td><td>识别</td><td>identify a pattern</td></tr><tr><td>damage</td><td>/ˈdæmɪdʒ/</td><td>n.</td><td>损坏</td><td>assess the damage</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in pieces — 成为碎片或散开状态</li><li>send in — 将材料寄送或提交给有关机构</li></ul><h2 id="语法讲解-可数与不可数名词" tabindex="-1">语法讲解：可数与不可数名词 <a class="header-anchor" href="#语法讲解-可数与不可数名词" aria-label="Permalink to &quot;语法讲解：可数与不可数名词&quot;">​</a></h2><p>money 和 damage 在一般意义下通常不可数，不直接加 a，也不以普通复数表达若干份。note、coin、fragment 则可数，需要根据数量使用复数形式。表达不可数名词的单位可用 a sum of money 或 a piece of evidence，但单位词必须符合实际语境。a number of 加复数名词通常接复数谓语，the amount of 加不可数名词通常接单数谓语。damage 在法律赔偿意义下有 damages 的特殊用法，不能反推所有语境都可数。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Several fragments were missing, but most of the printed number was still visible.</p></blockquote><p>几块碎片不见了，但印刷号码的大部分仍清晰可见。</p><p>several fragments 为复数；most of the printed number 指单个号码的部分，谓语用 was。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>many money 应为 much money 或 a lot of money；many banknotes 则正确，因为 banknote 可数。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 four torn tickets 和 one ticket，检查复数 s 是否可听见；把 remained clear 读得比连接词更突出。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We received four torn tickets. One ticket had lost its upper corner. The date remained clear on all four.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为受损物品写三句检查记录，交代数量、损坏和可识别特征。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>four 与 all four 准确对应，单数 ticket 的局部损坏没有被夸大成全部无法识别。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择：There was ___ damage.（much/many）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> damage 表示损坏时通常不可数。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>将 one fragment 改为三个。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> three fragments</p><p><strong>解析：</strong> 可数名词数量大于一时用复数。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句是说整个号码都看不见吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> most ... was still visible 表示大部分仍可见。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：可数与不可数名词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-006">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-008">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(i,[["render",l]]);export{p as __pageData,m as default};
